using System.Text.RegularExpressions;
using SysAdminAssistant.Core;
namespace SysAdminAssistant.Infrastructure;
public sealed class RouterUpdateCatalog
{
 private readonly SemaphoreSlim gate=new(1);private readonly Dictionary<string,(DateTime Retry,DateTime? Checked,string Version)> cache=[];
 public static OsUpdateStatus Compare(string installed,string available,DateTime? checkedUtc){var a=Regex.Match(installed,@"^\d+\.\d+(?:\.\d+)?(?=$|\s|\()").Value;var b=Regex.Match(available,@"^\d+\.\d+(?:\.\d+)?$").Value;if(!Version.TryParse(a,out var av)||!Version.TryParse(b,out var bv)||av.Major!=bv.Major)return new(){Installed=installed,Detail="Данные официального каталога недоступны; автоматическое обновление не выполняется"};return new(){State=bv>av?"Available":"Current",Installed=installed,Available=available,CheckedUtc=checkedUtc,Items=bv>av?["RouterOS stable "+available]:[],Detail="Официальный канал stable; только сведения о версии"};}
 public async Task<OsUpdateStatus> Read(string installed,CancellationToken token,string channel="stable"){if(channel is not("stable" or "long-term"))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Неверный канал RouterOS"));var match=Regex.Match(installed,@"^(6|7)\.");if(!match.Success)return new(){Installed=installed,Detail="Версия RouterOS не распознана"};int major=int.Parse(match.Groups[1].Value);await gate.WaitAsync(token);try{if(!cache.TryGetValue(major+channel,out var item)||DateTime.UtcNow>=item.Retry){try{using var handler=new HttpClientHandler{AllowAutoRedirect=false};using var http=new HttpClient(handler){Timeout=TimeSpan.FromSeconds(10)};var url="https://upgrade.mikrotik.com/routeros/"+(major==7?"NEWESTa7.":"NEWEST6.")+channel;using var response=await http.GetAsync(url,HttpCompletionOption.ResponseHeadersRead,token);response.EnsureSuccessStatusCode();await using var stream=await response.Content.ReadAsStreamAsync(token);var bytes=new byte[4097];int size=0,n;while((n=await stream.ReadAsync(bytes.AsMemory(size),token))>0){size+=n;if(size>4096)throw new IOException(global::SysAdminAssistant.Core.ProductText.Get("Каталог слишком велик"));}var version=System.Text.Encoding.UTF8.GetString(bytes,0,size).Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries).FirstOrDefault()??"";if(!Regex.IsMatch(version,@"^[67]\.\d+(?:\.\d+)?$"))throw new IOException(global::SysAdminAssistant.Core.ProductText.Get("Неверный каталог"));item=(DateTime.UtcNow.AddDays(1),DateTime.UtcNow,version);}catch(Exception e)when(e is HttpRequestException or IOException or TaskCanceledException){if(token.IsCancellationRequested)throw;item=(DateTime.UtcNow.AddHours(1),item.Checked,item.Version??"");}cache[major+channel]=item;}var status=Compare(installed,item.Version??"",item.Checked);status.Detail=status.Detail.Replace("stable",channel);status.Items=status.Items.Select(x=>x.Replace("stable",channel)).ToArray();return status;}finally{gate.Release();}}
}
